// 64 taps, each weighted by four dependent transcendental calls: 256 per pixel.
fn effect(uv: vec2f, src: vec4f) -> vec4f {
    var acc = vec4f(0.0);
    var total = 0.0;
    var w = 0.5;
    for (var i = 0u; i < 64u; i++) {
        let s = sample_src(fract(uv + vec2f(f32(i) * 0.0007, f32(i) * 0.0003)));
        w = sin(w * 1.37 + s.r);
        w = exp(-abs(w) * 0.7);
        w = sqrt(w + 0.01);
        w = cos(w * 0.91 + s.a);
        acc += s * w;
        total += abs(w);
    }
    return acc / max(total, 0.000001);
}
